#include "lmtorch/ops.hpp"
#include "lmtorch/safetensors.hpp"
#include <torch/torch.h>
#include <ATen/CPUGeneratorImpl.h>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <limits>
#include <random>
#include <charconv>

namespace {
using namespace lmcpp;
using lmtorch::TensorBundle;
using lmtorch::TensorData;
using lmtorch::TensorRef;
torch::ScalarType scalar_type(const std::string&d){if(d=="F32")return torch::kFloat32;if(d=="F64")return torch::kFloat64;if(d=="I64")return torch::kInt64;throw Error{ErrorCode::ValidationError,"dtype must be F32, F64, or I64",{{"tool_code","INVALID_DTYPE"}}};}
std::string dtype_name(torch::ScalarType t){if(t==torch::kFloat32)return "F32";if(t==torch::kFloat64)return "F64";if(t==torch::kInt64)return "I64";throw Error{ErrorCode::ValidationError,"unsupported tensor dtype",{{"tool_code","UNSUPPORTED_DTYPE"}}};}
torch::Tensor tensor_from(const TensorData&d){auto t=torch::empty(d.shape,torch::TensorOptions().dtype(scalar_type(d.dtype)).device(torch::kCPU));if(t.nbytes()!=d.bytes.size())throw Error{ErrorCode::CommandFailed,"tensor payload has invalid size",{{"tool_code","INVALID_ARTIFACT"}}};if(!d.bytes.empty())std::memcpy(t.data_ptr(),d.bytes.data(),d.bytes.size());return t;}
TensorData tensor_to(const torch::Tensor&input){auto t=input.contiguous().cpu();TensorData d;d.dtype=dtype_name(t.scalar_type());d.shape.assign(t.sizes().begin(),t.sizes().end());d.bytes.resize(t.nbytes());if(!d.bytes.empty())std::memcpy(d.bytes.data(),t.data_ptr(),d.bytes.size());return d;}
TensorRef ref(const Json&j,const char*k){return lmtorch::parse_ref(j.at(k).get<std::string>());}
TensorRef out_ref(const Json&j){auto path=j.at("out").get<std::string>();if(path.find('#')!=std::string::npos)throw Error{ErrorCode::ValidationError,"output path cannot contain #",{{"tool_code","INVALID_OUTPUT_PATH"}}};return{path,"tensor"};}
Param param(std::string n,Type t,bool req=true,std::string occurs="1",Json def=nullptr){Param p;p.name=std::move(n);p.type=t;p.occurs=std::move(occurs);if(!req&&(p.occurs=="1"||p.occurs=="+"))p.occurs="?";p.default_value=std::move(def);return p;}
Json desc(const TensorRef&r,const TensorData&d){return lmtorch::descriptor(r,d);}
Json descriptors(const TensorBundle&b,const std::string&path){Json out=Json::object();for(const auto&item:b.tensors)out[item.first]=desc({path,item.first},item.second);return out;}
void same_type_shape(const TensorData&a,const TensorData&b,const char*op){if(a.dtype!=b.dtype)throw Error{ErrorCode::ValidationError,std::string(op)+" inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(a.shape!=b.shape)throw Error{ErrorCode::ValidationError,std::string(op)+" inputs must have identical shapes",{{"tool_code","SHAPE_MISMATCH"}}};}
uint64_t positive_shape(const Json&j,std::vector<int64_t>&dims,const std::string&op="shape"){
  uint64_t n=1;for(const auto&v:j){if(!v.is_number_integer()&&!v.is_number_unsigned())throw Error{ErrorCode::ValidationError,op+" dimensions must be positive integers",{{"tool_code","INVALID_SHAPE"}}};int64_t d;try{d=v.get<int64_t>();}catch(...){throw Error{ErrorCode::ValidationError,op+" dimension is out of range",{{"tool_code","INVALID_SHAPE"}}};}if(d<1)throw Error{ErrorCode::ValidationError,op+" dimensions must be positive integers",{{"tool_code","INVALID_SHAPE"}}};if(n>256ull*1024*1024/8/static_cast<uint64_t>(d))throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};n*=static_cast<uint64_t>(d);dims.push_back(d);}if(dims.empty())throw Error{ErrorCode::ValidationError,op+" must not be empty",{{"tool_code","INVALID_SHAPE"}}};return n;
}
TensorData checkpoint_tensor(const TensorBundle&b,const char*name){auto it=b.tensors.find(name);if(it==b.tensors.end())throw Error{ErrorCode::ValidationError,std::string("checkpoint is missing ")+name,{{"tool_code","INVALID_CHECKPOINT"}}};return it->second;}
void check_checkpoint(const TensorBundle&b){auto f=b.metadata.find("torchcli_format"),a=b.metadata.find("arch");if(f==b.metadata.end()||f->second!="1"||a==b.metadata.end()||a->second!="mlp_relu_v1")throw Error{ErrorCode::ValidationError,"unsupported MLP checkpoint metadata",{{"tool_code","INVALID_CHECKPOINT"}}};}
uint64_t checkpoint_step(const TensorBundle&b);
struct MlpParams { torch::Tensor w1,b1,w2,b2; int64_t in=0,hidden=0,out=0; };
MlpParams validate_mlp(const TensorBundle&b){check_checkpoint(b);(void)checkpoint_step(b);MlpParams m;auto d1=checkpoint_tensor(b,"w1"),d2=checkpoint_tensor(b,"b1"),d3=checkpoint_tensor(b,"w2"),d4=checkpoint_tensor(b,"b2");if(d1.dtype!="F32"||d2.dtype!="F32"||d3.dtype!="F32"||d4.dtype!="F32"||d1.shape.size()!=2||d2.shape.size()!=1||d3.shape.size()!=2||d4.shape.size()!=1||d1.shape[0]<1||d1.shape[1]<1||d3.shape[0]<1||d2.shape[0]!=d1.shape[0]||d3.shape[1]!=d1.shape[0]||d4.shape[0]!=d3.shape[0])throw Error{ErrorCode::ValidationError,"invalid MLP checkpoint tensors",{{"tool_code","INVALID_CHECKPOINT"}}};m.hidden=d1.shape[0];m.in=d1.shape[1];m.out=d3.shape[0];m.w1=tensor_from(d1);m.b1=tensor_from(d2);m.w2=tensor_from(d3);m.b2=tensor_from(d4);return m;}
torch::Tensor forward_mlp(const MlpParams&m,const torch::Tensor&x){return x.matmul(m.w1.transpose(0,1)).add(m.b1).relu().matmul(m.w2.transpose(0,1)).add(m.b2);}
uint64_t checkpoint_step(const TensorBundle&b){auto it=b.metadata.find("step");if(it==b.metadata.end())return 0;uint64_t v=0;const auto&s=it->second;if(s.empty())throw Error{ErrorCode::ValidationError,"invalid checkpoint step metadata",{{"tool_code","INVALID_CHECKPOINT"}}};auto r=std::from_chars(s.data(),s.data()+s.size(),v);if(r.ec!=std::errc{}||r.ptr!=s.data()+s.size())throw Error{ErrorCode::ValidationError,"invalid checkpoint step metadata",{{"tool_code","INVALID_CHECKPOINT"}}};return v;}
}
lmcpp::CliSpec make_lmtorch_spec(){
  using namespace lmcpp;CliSpec spec{"lmtorch","0.2.0",{}};
  auto write_op=[](std::string name,std::string description){Operation o;o.name=std::move(name);o.access=Access::Write;o.description=std::move(description);o.returns="object";return o;};
  auto shape_param=param("shape",Type::Number,true,"+");
  Operation create=write_op("tensor_create","Create a dense CPU tensor artifact");auto dtype=param("dtype",Type::String,false,"?","F32");dtype.enum_values={"F32","F64","I64"};create.params={shape_param,dtype,param("fill",Type::Number,false),param("values",Type::Json,false),param("out",Type::String)};
  create.handler=[](const Params&p){std::string dtype=p.value("dtype","F32");auto st=scalar_type(dtype);std::vector<int64_t>dims;uint64_t count=positive_shape(p.at("shape"),dims);if(count>256ull*1024*1024/(st==torch::kFloat32?4:8))throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};if(p.contains("fill")&&p.contains("values"))throw Error{ErrorCode::ValidationError,"fill and values are mutually exclusive",{{"tool_code","INVALID_VALUE"}}};torch::Tensor t;
    auto numeric_value=[&](const Json&x){if(!x.is_number())throw Error{ErrorCode::ValidationError,"values must be numbers",{{"tool_code","INVALID_VALUE"}}};double n=x.get<double>();if(!std::isfinite(n))throw Error{ErrorCode::ValidationError,"values must be finite",{{"tool_code","INVALID_VALUE"}}};if(st==torch::kFloat32&&std::abs(n)>std::numeric_limits<float>::max())throw Error{ErrorCode::ValidationError,"F32 value is out of range",{{"tool_code","INVALID_VALUE"}}};return n;};
    auto integer_value=[&](const Json&x){if(!x.is_number())throw Error{ErrorCode::ValidationError,"values must be numbers",{{"tool_code","INVALID_VALUE"}}};if(x.is_number_unsigned()){auto n=x.get<uint64_t>();if(n>static_cast<uint64_t>(std::numeric_limits<int64_t>::max()))throw Error{ErrorCode::ValidationError,"I64 value is out of range",{{"tool_code","INVALID_VALUE"}}};return static_cast<int64_t>(n);}if(x.is_number_integer())return x.get<int64_t>();double n=x.get<double>();if(!std::isfinite(n)||std::floor(n)!=n||std::abs(n)>9007199254740991.0)throw Error{ErrorCode::ValidationError,"I64 values must be exact integers",{{"tool_code","INVALID_VALUE"}}};return static_cast<int64_t>(n);};
    auto options=torch::TensorOptions().dtype(st).device(torch::kCPU);
    if(p.contains("values")){const Json&v=p.at("values");if(!v.is_array()||v.size()!=count)throw Error{ErrorCode::ValidationError,"values count must match shape",{{"tool_code","INVALID_VALUE"}}};if(st==torch::kInt64){std::vector<int64_t>vals;for(const auto&x:v)vals.push_back(integer_value(x));t=torch::tensor(vals,options).reshape(dims);}else{std::vector<double>vals;for(const auto&x:v)vals.push_back(numeric_value(x));t=torch::tensor(vals,options).reshape(dims);}}else if(st==torch::kInt64){t=torch::full(dims,integer_value(p.value("fill",Json(0))),options);}else{double value=numeric_value(p.value("fill",Json(0.0)));t=torch::full(dims,value,options);}
    auto data=tensor_to(t);auto r=out_ref(p);lmtorch::write_tensor(r.path,data);return desc(r,data);};
  Operation rand=write_op("tensor_rand","Create a seeded uniform tensor artifact");rand.params={shape_param,param("dtype",Type::String,false,"?","F32"),param("distribution",Type::String,false,"?","uniform"),param("seed",Type::Number),param("out",Type::String)};rand.params[1].enum_values={"F32","F64","I64"};rand.params[2].enum_values={"uniform"};
  rand.handler=[](const Params&p){std::vector<int64_t>dims;uint64_t count=positive_shape(p.at("shape"),dims);auto st=scalar_type(p.value("dtype","F32"));std::string dt=dtype_name(st);if(count>256ull*1024*1024/(st==torch::kFloat32?4:8))throw Error{ErrorCode::ValidationError,"tensor exceeds artifact size limit",{{"tool_code","OUTPUT_TOO_LARGE"}}};double seed_value=p.at("seed").get<double>();if(!std::isfinite(seed_value)||seed_value<0||std::floor(seed_value)!=seed_value||seed_value>9007199254740991.0)throw Error{ErrorCode::ValidationError,"seed must be a nonnegative safe integer",{{"tool_code","INVALID_SEED"}}};uint64_t seed=static_cast<uint64_t>(seed_value);auto generator=at::detail::createCPUGenerator(seed);auto options=torch::TensorOptions().dtype(st).device(torch::kCPU);auto t=st==torch::kInt64?torch::randint(0,1000,dims,generator,options):torch::rand(dims,generator,options);auto data=tensor_to(t);auto r=out_ref(p);lmtorch::write_tensor(r.path,data);auto result=desc(r,data);result["seed"]=seed;return result;};
  Operation matmul=write_op("tensor_matmul","Multiply two rank-2 dense CPU tensors");matmul.params={param("a",Type::String),param("b",Type::String),param("out",Type::String)};matmul.handler=[](const Params&p){auto ar=ref(p,"a"),br=ref(p,"b"),or_=out_ref(p);auto ad=lmtorch::read_tensor(ar),bd=lmtorch::read_tensor(br);if(ad.dtype!=bd.dtype)throw Error{ErrorCode::ValidationError,"matmul inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(ad.shape.size()!=2||bd.shape.size()!=2||ad.shape[1]!=bd.shape[0])throw Error{ErrorCode::ValidationError,"matmul requires compatible rank-2 shapes",{{"tool_code","SHAPE_MISMATCH"}}};auto data=tensor_to(tensor_from(ad).matmul(tensor_from(bd)));lmtorch::write_tensor(or_.path,data);return desc(or_,data);};
  Operation add=write_op("tensor_add","Add equal-shaped tensors without broadcasting");add.params={param("a",Type::String),param("b",Type::String),param("out",Type::String)};add.handler=[](const Params&p){auto ar=ref(p,"a"),br=ref(p,"b"),or_=out_ref(p);auto ad=lmtorch::read_tensor(ar),bd=lmtorch::read_tensor(br);same_type_shape(ad,bd,"add");auto data=tensor_to(tensor_from(ad)+tensor_from(bd));lmtorch::write_tensor(or_.path,data);return desc(or_,data);};
  Operation soft=write_op("tensor_softmax","Apply softmax along a checked dimension");soft.params={param("input",Type::String),param("dim",Type::Number),param("out",Type::String)};soft.handler=[](const Params&p){auto ir=ref(p,"input"),or_=out_ref(p);auto d=lmtorch::read_tensor(ir);if(d.dtype=="I64")throw Error{ErrorCode::ValidationError,"softmax requires floating point input",{{"tool_code","INVALID_DTYPE"}}};auto t=tensor_from(d);double dim_value=p.at("dim").get<double>();if(!std::isfinite(dim_value)||std::floor(dim_value)!=dim_value||static_cast<long double>(dim_value)<static_cast<long double>(std::numeric_limits<int64_t>::min())||static_cast<long double>(dim_value)>static_cast<long double>(std::numeric_limits<int64_t>::max()))throw Error{ErrorCode::ValidationError,"softmax dimension must be an integer",{{"tool_code","INVALID_DIM"}}};int64_t dim=static_cast<int64_t>(dim_value);if(dim<0)dim+=t.dim();if(dim<0||dim>=t.dim())throw Error{ErrorCode::ValidationError,"softmax dimension out of range",{{"tool_code","INVALID_DIM"}}};auto data=tensor_to(torch::softmax(t,dim));lmtorch::write_tensor(or_.path,data);return desc(or_,data);};
  Operation linear=write_op("tensor_linear","Apply X W-transpose plus optional bias");linear.params={param("input",Type::String),param("weight",Type::String),param("bias",Type::String,false,"?"),param("out",Type::String)};linear.handler=[](const Params&p){auto ir=ref(p,"input"),wr=ref(p,"weight"),or_=out_ref(p);auto xd=lmtorch::read_tensor(ir),wd=lmtorch::read_tensor(wr);if(xd.dtype!=wd.dtype)throw Error{ErrorCode::ValidationError,"linear inputs must have matching dtypes",{{"tool_code","DTYPE_MISMATCH"}}};if(xd.dtype=="I64")throw Error{ErrorCode::ValidationError,"linear requires floating point tensors",{{"tool_code","INVALID_DTYPE"}}};auto x=tensor_from(xd),w=tensor_from(wd);if(w.dim()!=2||x.dim()<1||x.size(-1)!=w.size(1))throw Error{ErrorCode::ValidationError,"linear input and weight shapes are incompatible",{{"tool_code","SHAPE_MISMATCH"}}};auto y=x.matmul(w.transpose(0,1));if(p.contains("bias")){auto bd=lmtorch::read_tensor(lmtorch::parse_ref(p.at("bias").get<std::string>()));if(bd.dtype!=xd.dtype||bd.shape!=std::vector<int64_t>{w.size(0)})throw Error{ErrorCode::ValidationError,"linear bias shape or dtype mismatch",{{"tool_code","SHAPE_MISMATCH"}}};y=y+tensor_from(bd);}auto data=tensor_to(y);lmtorch::write_tensor(or_.path,data);return desc(or_,data);};
  Operation save=write_op("tensor_save","Pack named tensor references into one safetensors artifact");save.params={param("tensors",Type::Object),param("out",Type::String),param("metadata",Type::Object,false)};save.handler=[](const Params&p){TensorBundle b;for(auto it=p.at("tensors").begin();it!=p.at("tensors").end();++it){if(!it.value().is_string())throw Error{ErrorCode::ValidationError,"tensor refs must be strings",{{"tool_code","INVALID_TENSOR_REF"}}};if(it.key().empty()||it.key()=="__metadata__")throw Error{ErrorCode::ValidationError,"invalid tensor name",{{"tool_code","INVALID_TENSOR_NAME"}}};auto r=lmtorch::parse_ref(it.value().get<std::string>());b.tensors.emplace(it.key(),lmtorch::read_tensor(r));}if(p.contains("metadata")){for(auto it=p.at("metadata").begin();it!=p.at("metadata").end();++it){if(!it.value().is_string())throw Error{ErrorCode::ValidationError,"metadata values must be strings",{{"tool_code","INVALID_METADATA"}}};b.metadata[it.key()]=it.value().get<std::string>();}}auto path=out_ref(p).path;lmtorch::write_bundle(path,b);return Json{{"path",path},{"tensors",descriptors(b,path)}};};
  Operation load=write_op("tensor_load","Validate and reserialize safetensors into a new artifact");load.params={param("path",Type::String),param("key",Type::String,false,"?"),param("out",Type::String)};load.handler=[](const Params&p){auto b=lmtorch::read_bundle(p.at("path").get<std::string>());if(p.contains("key")){auto it=b.tensors.find(p.at("key").get<std::string>());if(it==b.tensors.end())throw Error{ErrorCode::NotFound,"tensor key not found",{{"tool_code","TENSOR_NOT_FOUND"}}};TensorData selected=it->second;b.tensors.clear();b.tensors.emplace(p.at("key").get<std::string>(),std::move(selected));}auto path=out_ref(p).path;lmtorch::write_bundle(path,b);return Json{{"path",path},{"tensors",descriptors(b,path)}};};
  Operation inspect;inspect.name="tensor_inspect";inspect.access=Access::Read;inspect.description="Inspect tensor metadata and a bounded value preview";inspect.returns="object";inspect.params={param("input",Type::String),param("limit",Type::Number,false,"?",32)};inspect.handler=[](const Params&p){auto r=ref(p,"input");auto d=lmtorch::read_tensor(r);auto t=tensor_from(d);double lim=p.value("limit",32.0);if(!std::isfinite(lim)||lim<0||std::floor(lim)!=lim||lim>32)throw Error{ErrorCode::ValidationError,"limit must be an integer from 0 through 32",{{"tool_code","INVALID_LIMIT"}}};Json values=Json::array();uint64_t nonfinite=0;uint64_t n=static_cast<uint64_t>(t.numel()),take=std::min<uint64_t>(n,static_cast<uint64_t>(lim));for(uint64_t i=0;i<n;++i)if(t.scalar_type()!=torch::kInt64){double x=t.scalar_type()==torch::kFloat32?static_cast<double>(t.data_ptr<float>()[i]):t.data_ptr<double>()[i];if(!std::isfinite(x))++nonfinite;}for(uint64_t i=0;i<take;++i){if(t.scalar_type()==torch::kInt64)values.push_back(t.data_ptr<int64_t>()[i]);else{double x=t.scalar_type()==torch::kFloat32?static_cast<double>(t.data_ptr<float>()[i]):t.data_ptr<double>()[i];if(std::isfinite(x))values.push_back(x);else values.push_back(nullptr);}}auto result=desc(r,d);result["values"]=values;result["nonfinite_count"]=nonfinite;return result;};
  Operation grad=write_op("autograd_grad","Rebuild sum-of-squares graph and persist its gradient");grad.params={param("input",Type::String),param("function",Type::String,false,"?","sum_square"),param("out",Type::String)};grad.params[1].enum_values={"sum_square"};grad.handler=[](const Params&p){auto ir=ref(p,"input"),or_=out_ref(p);auto d=lmtorch::read_tensor(ir);if(d.dtype=="I64")throw Error{ErrorCode::ValidationError,"autograd requires floating point input",{{"tool_code","INVALID_DTYPE"}}};auto x=tensor_from(d).detach().set_requires_grad(true);auto loss=x.pow(2).sum();loss.backward();auto dx=tensor_to(x.grad());lmtorch::write_tensor(or_.path,dx);return Json{{"dx",desc(or_,dx)},{"loss",loss.item<double>()}};};
  Operation forward=write_op("mlp_forward","Run fixed two-layer ReLU MLP inference");forward.params={param("checkpoint",Type::String),param("input",Type::String),param("out",Type::String)};forward.handler=[](const Params&p){auto bundle=lmtorch::read_bundle(p.at("checkpoint").get<std::string>());auto m=validate_mlp(bundle);auto xdata=lmtorch::read_tensor(ref(p,"input"));if(xdata.dtype!="F32"||xdata.shape.empty()||xdata.shape.back()!=m.in)throw Error{ErrorCode::ValidationError,"MLP input must be F32 with final dimension matching checkpoint",{{"tool_code","INVALID_CHECKPOINT"}}};auto x=tensor_from(xdata);torch::NoGradGuard guard;auto data=tensor_to(forward_mlp(m,x));auto r=out_ref(p);lmtorch::write_tensor(r.path,data);return desc(r,data);};
  Operation train=write_op("mlp_train_step","Train one MLP step with MSE and plain SGD");train.params={param("checkpoint",Type::String),param("input",Type::String),param("target",Type::String),param("lr",Type::Number),param("out",Type::String)};train.handler=[](const Params&p){auto bundle=lmtorch::read_bundle(p.at("checkpoint").get<std::string>());auto m=validate_mlp(bundle);auto xd=lmtorch::read_tensor(ref(p,"input")),yd=lmtorch::read_tensor(ref(p,"target"));if(xd.dtype!="F32"||yd.dtype!="F32"||xd.shape.empty()||xd.shape.back()!=m.in||xd.shape.size()!=2||yd.shape.size()!=2||yd.shape[0]!=xd.shape[0]||yd.shape[1]!=m.out)throw Error{ErrorCode::ValidationError,"MLP input and target must be matching F32 batches",{{"tool_code","INVALID_CHECKPOINT"}}};auto x=tensor_from(xd),y=tensor_from(yd);double lr=p.at("lr").get<double>();if(!std::isfinite(lr)||lr<=0||lr>10)throw Error{ErrorCode::ValidationError,"learning rate must be finite and in (0,10]",{{"tool_code","INVALID_LR"}}};m.w1=m.w1.detach().set_requires_grad(true);m.b1=m.b1.detach().set_requires_grad(true);m.w2=m.w2.detach().set_requires_grad(true);m.b2=m.b2.detach().set_requires_grad(true);auto prediction=forward_mlp(m,x);auto loss=torch::mse_loss(prediction,y);loss.backward();{torch::NoGradGuard guard;m.w1.sub_(m.w1.grad()*lr);m.b1.sub_(m.b1.grad()*lr);m.w2.sub_(m.w2.grad()*lr);m.b2.sub_(m.b2.grad()*lr);}bundle.tensors["w1"]=tensor_to(m.w1);bundle.tensors["b1"]=tensor_to(m.b1);bundle.tensors["w2"]=tensor_to(m.w2);bundle.tensors["b2"]=tensor_to(m.b2);uint64_t step=checkpoint_step(bundle);if(step==std::numeric_limits<uint64_t>::max())throw Error{ErrorCode::ValidationError,"checkpoint step overflows",{{"tool_code","INVALID_CHECKPOINT"}}};bundle.metadata["torchcli_format"]="1";bundle.metadata["arch"]="mlp_relu_v1";bundle.metadata["step"]=std::to_string(step+1);auto path=out_ref(p).path;lmtorch::write_bundle(path,bundle);return Json{{"path",path},{"tensors",descriptors(bundle,path)},{"loss",loss.item<double>()},{"step",step+1}};};
  spec.operations={create,rand,matmul,add,soft,linear,save,load,inspect,grad,forward,train};for(auto&o:spec.operations){if(!o.handler)continue;auto original=o.handler;o.handler=[original](const Params&p)->Json{try{return original(p);}catch(const c10::Error&e){std::string line=e.what();auto pos=line.find('\n');if(pos!=std::string::npos)line.resize(pos);if(line.size()>240)line.resize(240);throw Error{ErrorCode::ValidationError,"invalid tensor operation: "+line,{{"tool_code","INVALID_CHECKPOINT"}}};}};}return spec;
}
